#!/usr/bin/env python3
"""Check the actual packaged built-in executables, without extracting the runtime."""
import argparse
import hashlib
import json
import shlex
from pathlib import Path, PureWindowsPath
import struct
import zipfile



def audit_native_optimization(path):
    # Read the compiler commands actually generated by CMake. A debug signed
    # package may still have Release native code; signing is not an indicator.
    hot_paths = (
        'direct/direct_vulkan_desktop_compositor.cpp',
        'compositor/toplevel/desktop_compositor.cpp',
        'graphics/egl_renderer.cpp',
        'graphics/virgl_surface_presenter.cpp',
    )
    commands = json.loads(path.read_text(encoding='utf-8'))
    rows, errors = [], []
    for suffix in hot_paths:
        matching = [entry for entry in commands
                    if entry['file'].replace('\\', '/').endswith('/' + suffix)]
        if not matching:
            errors.append(f'native performance audit: missing compiler command for {suffix}')
        for entry in matching:
            arguments = entry.get('arguments')
            if arguments is None:
                arguments = shlex.split(entry['command'])
            levels = [arg for arg in arguments if arg.startswith('-O')]
            effective = levels[-1] if levels else None
            rows.append({'source': suffix, 'optimization': effective,
                         'output': entry.get('output', '')})
            if effective not in ('-O1', '-O2', '-O3', '-Os', '-Oz', '-Ofast'):
                errors.append(f'native performance audit: {suffix} uses {effective or "no optimization flag"}')
    return rows, errors


def main():
    root = Path(__file__).resolve().parents[1]
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--runtime', type=Path,
                        default=root / 'entry/src/main/resources/rawfile/wine-data.zip')
    parser.add_argument('--catalog', type=Path,
                        default=root / 'entry/src/main/resources/rawfile/builtin_apps/catalog.json')
    parser.add_argument('--output', type=Path)
    parser.add_argument('--native-compile-commands', type=Path,
                        help='Require optimized graphics hot paths for performance validation')
    args = parser.parse_args()
    catalog = json.loads(args.catalog.read_text(encoding='utf-8'))
    rows, errors = [], []
    with zipfile.ZipFile(args.runtime) as runtime:
        for app in catalog['apps']:
            executable = app['launchParams']['executable']
            normalized = executable.replace('\\', '/').lower()
            if normalized.startswith('c:/smoke/'):
                member = executable[3:].replace('\\', '/')
            elif '/' not in normalized or normalized.startswith('c:/windows/system32/'):
                # Built-in Wine executables are packaged in bin/ and installed
                # by wineboot into C:\windows\system32; x64/ smoke is a legacy
                # directory label, not a guarantee of the PE machine type.
                member = 'bin/' + PureWindowsPath(executable).name
            else:
                errors.append(f"{app['id']}: unsupported executable location {executable}")
                continue
            row = {'id': app['id'], 'enabled': app.get('enabled', True),
                   'renderModes': app.get('renderModes'), 'executable': executable,
                   'runtimeMember': member}
            try:
                data = runtime.read(member)
                pe = struct.unpack_from('<I', data, 0x3c)[0]
                if data[:2] != b'MZ' or data[pe:pe+4] != b'PE\0\0':
                    raise ValueError('invalid PE executable')
                machine = struct.unpack_from('<H', data, pe + 4)[0]
                row.update(bytes=len(data), machine=f'0x{machine:04x}',
                           sha256=hashlib.sha256(data).hexdigest())
                if row['enabled'] and machine not in (0xaa64, 0xa641, 0xa64e):
                    errors.append(f"{app['id']}: enabled built-in is not native ARM64/ARM64EC/ARM64X")
                directory = app['launchParams'].get('workingDirectory', '').replace('\\', '/')
                if directory.lower().startswith('c:/smoke/') and not member.startswith(directory[3:] + '/'):
                    errors.append(f"{app['id']}: working directory does not contain executable")
            except (KeyError, ValueError, struct.error) as error:
                errors.append(f"{app['id']}: {member}: {error}")
            rows.append(row)
    result = {'status': 'PASS' if not errors else 'FAIL', 'apps': rows, 'errors': errors}
    if args.native_compile_commands:
        native, native_errors = audit_native_optimization(args.native_compile_commands)
        result['nativeOptimization'] = native
        errors.extend(native_errors)
        result['status'] = 'PASS' if not errors else 'FAIL'
    encoded = json.dumps(result, ensure_ascii=False, indent=2) + '\n'
    if args.output:
        args.output.write_text(encoded, encoding='utf-8')
    print(f"{result['status']}: {len(rows)} catalog entries, {sum(row['enabled'] for row in rows)} enabled, {len(errors)} errors")
    for error in errors:
        print(error)
    return bool(errors)


if __name__ == '__main__':
    raise SystemExit(main())
